package com.moodlight.app;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.provider.Settings;import android.view.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
  MoodView view;
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(Color.rgb(16,19,19)); view=new MoodView(this); setContentView(view);}
  void exportData(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"moodlight-backup.json");startActivityForResult(i,10);}
  void importData(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);}
  @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;try{if(r==10){OutputStream o=getContentResolver().openOutputStream(d.getData());o.write(view.json().getBytes());o.close();}else{InputStream in=getContentResolver().openInputStream(d.getData());ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] z=new byte[4096];int n;while((n=in.read(z))>0)b.write(z,0,n);in.close();view.load(b.toString());}}catch(Exception e){}}
}

class Entry { long t; int score; String note; Entry(long a,int b,String c){t=a;score=b;note=c;} }

class MoodView extends View {
  Paint p=new Paint(3); Paint stroke=new Paint(3); MainActivity a; ArrayList<Entry> entries=new ArrayList<>(); int page=0, selected=-1; String note=""; float density; long burstUntil=0; Random random=new Random(4); ArrayList<float[]> sparks=new ArrayList<>(); float scroll=0, downY=0;
  int bg=Color.rgb(16,19,19), card=Color.rgb(29,34,33), text=Color.rgb(242,244,235), muted=Color.rgb(157,167,156), lime=Color.rgb(214,255,101), cyan=Color.rgb(105,228,203);
  MoodView(MainActivity c){super(c);a=c;density=getResources().getDisplayMetrics().density; p.setTypeface(Typeface.create("sans",0));stroke.setStyle(Paint.Style.STROKE);stroke.setStrokeCap(Paint.Cap.ROUND);setFocusable(true);loadPrefs();}
  float d(float n){return n*density;} void txt(Canvas c,String s,float x,float y,float size,int col){p.setStyle(Paint.Style.FILL);p.setColor(col);p.setTextSize(d(size));p.setTypeface(Typeface.create("sans",Typeface.NORMAL));c.drawText(s,d(x),d(y),p);} void bold(Canvas c,String s,float x,float y,float size,int col){p.setTypeface(Typeface.create("sans",Typeface.BOLD));p.setTextSize(d(size));p.setColor(col);c.drawText(s,d(x),d(y),p);}
  protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(bg); if(page==0)home(c); else if(page==1)insights(c); else settings(c); nav(c); if(burstUntil>System.currentTimeMillis()){drawBurst(c);postInvalidateDelayed(16);}}
  void header(Canvas c,String title,String sub){bold(c,title,24,48,28,text);txt(c,sub,24,72,13,muted);}
  void home(Canvas c){header(c,"Good evening.","A tiny check-in for your inner weather."); round(c,20,101,355,198,card,24);txt(c,"How are you feeling?",38,130,14,muted);String[] emo={"drained","low","uneasy","okay","steady","bright","good","great","joyful","radiant","peak"};for(int i=0;i<11;i++){float x=39+(i%6)*51,y=149+(i/6)*43;float r=18; p.setColor(i==selected?lime:Color.rgb(48,55,52));p.setStyle(Paint.Style.FILL);c.drawCircle(d(x),d(y),d(r),p);bold(c,""+i,x-4.5f,y+5,13,i==selected?bg:text); if(i==selected)txt(c,emo[i],x-19,y+33,9,lime);}
    round(c,20,318,355,374,Color.rgb(24,29,28),18);txt(c,"Add a note  ·  optional",38,344,13,muted);if(note.length()>0)txt(c,note,38,365,14,text);else txt(c,"What shaped this moment?",38,365,14,Color.rgb(104,114,106));
    round(c,20,394,355,448,selected>=0?lime:Color.rgb(52,61,56),18);bold(c,selected>=0?"Save this moment":"Choose a score first",selected>=0?131:111,428,15,selected>=0?bg:muted);
    if(entries.size()>0){txt(c,"LATEST",24,489,11,muted);Entry e=entries.get(0);bold(c,""+e.score,24,523,34,lime);txt(c,ago(e.t),65,515,13,text);txt(c,e.note.length()>0?e.note:"No note added",65,535,12,muted);}
  }
  void insights(Canvas c){header(c,"Your rhythm","The last seven days, at a glance.");round(c,20,101,355,300,card,24);bold(c,avgText(),38,136,22,text);txt(c,"7-day mood flow",38,158,12,muted);drawChart(c);txt(c,"HISTORY",24,344,11,muted);c.save();c.clipRect(d(0),d(355),getWidth(),getHeight()-d(56));float y=371-scroll;int shown=0;for(Entry e:entries){if(y>getHeight()/density-55){y+=57;continue;}if(y>345){p.setColor(scoreColor(e.score));p.setStyle(Paint.Style.FILL);c.drawCircle(d(36),d(y-5),d(13),p);bold(c,""+e.score,30,y,11,bg);txt(c,time(e.t),64,y-5,13,text);txt(c,e.note.length()>0?e.note:"A quiet check-in",64,y+15,12,muted);shown++;}y+=57;}c.restore();if(entries.size()==0)txt(c,"Your check-ins will bloom here.",24,381,14,muted);}
  void drawChart(Canvas c){float x0=42,y0=269,w=307,h=85;stroke.setColor(Color.rgb(65,75,69));stroke.setStrokeWidth(d(1));for(int i=0;i<4;i++)c.drawLine(d(x0),d(y0-i*27),d(x0+w),d(y0-i*27),stroke);ArrayList<Entry> last=new ArrayList<>();long now=System.currentTimeMillis();for(Entry e:entries)if(now-e.t<7*86400000L)last.add(e);if(last.size()==0){txt(c,"No data yet",157,245,12,muted);return;}Collections.reverse(last);Path path=new Path();for(int i=0;i<last.size();i++){float xx=x0+(last.size()==1?w/2:w*i/(float)(last.size()-1));float yy=y0-last.get(i).score*h/10f;if(i==0)path.moveTo(d(xx),d(yy));else{float px=x0+(last.size()==1?w/2:w*(i-1)/(float)(last.size()-1));float py=y0-last.get(i-1).score*h/10f;float mid=(px+xx)/2;path.cubicTo(d(mid),d(py),d(mid),d(yy),d(xx),d(yy));}}stroke.setColor(lime);stroke.setStrokeWidth(d(3));c.drawPath(path,stroke);for(int i=0;i<last.size();i++){float xx=x0+(last.size()==1?w/2:w*i/(float)(last.size()-1));float yy=y0-last.get(i).score*h/10f;p.setColor(lime);p.setStyle(Paint.Style.FILL);c.drawCircle(d(xx),d(yy),d(4),p);}}
  String avgText(){if(entries.isEmpty())return "Your mood, mapped.";int s=0,n=0;long now=System.currentTimeMillis();for(Entry e:entries)if(now-e.t<7*86400000L){s+=e.score;n++;}return n==0?"Your mood, mapped.":(s/(float)n>=7?"A bright little week.":s/(float)n>=4?"A gentle, steady week.":"Making space for better days.");}
  void settings(Canvas c){header(c,"Settings","Your data stays yours.");round(c,20,104,355,180,card,20);bold(c,"Backup & restore",38,136,16,text);txt(c,"Move your moments as a simple JSON file.",38,157,12,muted);round(c,38,192,196,238,lime,15);bold(c,"Export JSON",73,221,13,bg);round(c,207,192,337,238,Color.rgb(51,62,57),15);bold(c,"Import JSON",237,221,13,text);round(c,20,264,355,324,card,18);txt(c,"MOODLIGHT",38,291,11,lime);txt(c,"Small check-ins. A clearer inner forecast.",38,310,12,muted);}
  void nav(Canvas c){float y=getHeight()/density-49; p.setColor(Color.rgb(23,28,27));p.setStyle(Paint.Style.FILL);c.drawRect(0,d(y-22),getWidth(),getHeight(),p);String[] n={"Today","Rhythm","Settings"};for(int i=0;i<3;i++){float x=59+i*126;if(page==i){p.setColor(lime);c.drawCircle(d(x),d(y-2),d(3),p);}txt(c,n[i],x-20,y+20,11,page==i?text:muted);}}
  void drawBurst(Canvas c){float age=(System.currentTimeMillis()-burstUntil+1200)/1200f;float cx=getWidth()/2f,cy=getHeight()/2f;for(float[] q:sparks){float x=cx+q[0]*age*d(220), y=cy+q[1]*age*d(220);p.setColor(Color.argb((int)(180*(1-age)),q[3]>0?214:105,q[3]>0?255:228,q[3]>0?101:203));c.drawCircle(x,y,d(3+q[2]*5),p);}p.setColor(Color.argb((int)(170*(1-age)),214,255,101));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d(2));c.drawCircle(cx,cy,d(40+age*180),p);}
  void round(Canvas c,float l,float t,float r,float b,int col,float rad){p.setStyle(Paint.Style.FILL);p.setColor(col);c.drawRoundRect(d(l),d(t),d(r),d(b),d(rad),d(rad),p);}int scoreColor(int s){return Color.rgb(120+Math.min(130,s*13),190+Math.min(60,s*6),120+Math.min(100,s*8));}
  public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX()/density,y=e.getY()/density; if(e.getAction()==0){downY=y;return true;} if(e.getAction()==2&&page==1){float dy=downY-y;if(Math.abs(dy)>1){scroll=Math.max(0,Math.min(Math.max(0,entries.size()*57-260),scroll+dy));downY=y;invalidate();}return true;} if(e.getAction()!=1)return true;float h=getHeight()/density;if(y>h-85){if(x<125)page=0;else if(x<250)page=1;else page=2;scroll=0;invalidate();return true;}if(page==0){if(y>130&&y<255){int row=(int)((y-131)/43),col=(int)((x-20)/51);int s=row*6+col;if(s>=0&&s<11)selected=s;invalidate();}else if(y>394&&y<465&&selected>=0){entries.add(0,new Entry(System.currentTimeMillis(),selected,note));savePrefs();burst();selected=-1;note="";invalidate();}else if(y>318&&y<390){final EditTextBox box=new EditTextBox(a,note);box.show();box.setOnDismissListener(d->{note=box.value;invalidate();});}}else if(page==2){if(y>185&&y<250&&x<205)a.exportData();else if(y>185&&y<250)a.importData();}return true;}
  void burst(){burstUntil=System.currentTimeMillis();sparks.clear();for(int i=0;i<52;i++){double z=random.nextDouble()*Math.PI*2;sparks.add(new float[]{(float)Math.cos(z),(float)Math.sin(z),(float)random.nextDouble(),random.nextBoolean()?1:0});}}
  String time(long t){return new SimpleDateFormat("MMM d  ·  HH:mm",Locale.getDefault()).format(new Date(t));}String ago(long t){long m=(System.currentTimeMillis()-t)/60000;return m<1?"Just now":m<60?m+" min ago":m<1440?(m/60)+" hr ago":(m/1440)+" day ago";}
  String json(){StringBuilder s=new StringBuilder("[\n");for(int i=0;i<entries.size();i++){Entry e=entries.get(i);s.append("{\"time\":").append(e.t).append(",\"score\":").append(e.score).append(",\"note\":\"").append(e.note.replace("\"","\\\"")).append("\"}").append(i+1<entries.size()?",\n":"\n");}return s.append("]").toString();}
  void load(String j){try{entries.clear();java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\{\\\"time\\\":(\\d+),\\\"score\\\":(\\d+),\\\"note\\\":\\\"(.*?)\\\"\\}").matcher(j);while(m.find())entries.add(new Entry(Long.parseLong(m.group(1)),Integer.parseInt(m.group(2)),m.group(3).replace("\\\"","\"")));savePrefs();invalidate();}catch(Exception e){}}
  void savePrefs(){a.getPreferences(0).edit().putString("data",json()).apply();}void loadPrefs(){String j=a.getPreferences(0).getString("data","[]");load(j);}
}

class EditTextBox extends Dialog {android.widget.EditText input;String value;EditTextBox(Context c,String v){super(c);value=v;}protected void onCreate(Bundle b){super.onCreate(b);input=new android.widget.EditText(getContext());input.setHint("A few words, if you want");input.setText(value);input.setSingleLine(false);input.setPadding(32,20,32,20);setContentView(input);Window w=getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.rgb(29,34,33)));w.setLayout(-1,-2);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);}input.setOnEditorActionListener((v,a,e)->{value=input.getText().toString();dismiss();return true;});}public void show(){super.show();input.postDelayed(()->{if(input!=null){input.requestFocus();((android.view.inputmethod.InputMethodManager)getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,0);}},180);}}
